#include <stdio.h>
#include <string.h>

/* Simple lines; for real CSV (quotes/commas) use libcsv or similar. */
int main(void) {
    FILE *f = fopen("data.csv", "r");
    if (!f) return 1;
    char line[512];
    while (fgets(line, sizeof line, f)) {
        char *nl = strchr(line, '\n'); if (nl) *nl = 0;
        char *tok = strtok(line, ",");
        while (tok) { printf("[%s] ", tok); tok = strtok(NULL, ","); }
        printf("\n");
    }
    fclose(f);
    return 0;
}

