#include <stdio.h>
#include <sys/stat.h>
#include <unistd.h>

int main(void) {
    mode_t old = umask(022); /* clear write for group/other */
    int fd = open("secret.txt", O_CREAT|O_WRONLY|O_TRUNC, 0600);
    if (fd < 0) return 1;
    write(fd, "x", 1);
    close(fd);
    chmod("secret.txt", 0640);
    umask(old);
    return 0;
}

